PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?entity ?label ?comment WHERE {
  ?entity a brick:Zone .
  FILTER (CONTAINS(str(?entity), "Z01") || ?entity=ref:Zone_F3_Z01)
  OPTIONAL { ?entity rdfs:label ?label }
  OPTIONAL { ?entity brick:hasSubArea ?sa }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?name WHERE {
  ?n rdfs:label ?name
  FILTER(?name="Core_mid")
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?entity ?class ?label ?comment ?tsid WHERE {
  ?entity rdfs:label "Core_mid" .
  a ?class2 .
  OPTIONAL { ?entity brick:hasLabel ?label }
  OPTIONAL { ?entity rdfs:comment ?comment }
  { a ?class }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ref: <urn:ref#>
SELECT ?entity ?label ?comment WHERE {
  ?entity rdfs:label "Core_mid" .
  OPTIONAL { ?entity rdfs:comment ?comment }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ref: <urn:ref#>
SELECT ?entity ?class ?sensor ?sclass ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label "Core_mid" .
  OPTIONAL { ?p brick:hasSensor ?sensor . OPTIONAL { ?sensor a ?sclass } . ?sensor ref:hasTimeseriesId ?tsid } WHERE {
}

SELECT * WHERE {
  ?s a brick:ZoneTemperatureSensor .
  ?s ref:hasTimeseriesId ?tsid .
  ?s rdfs:label ?label
} LIMIT 30

SELECT ?o ?class WHERE {
  ?in a brick:Zone .
  ?in rdfs:label "Core_mid" .
  ?p brick:hasProperty ?in .
  ?p ?class ?o
}
